import functools
import random
import time
import requests
from requests.exceptions import RequestException, HTTPError

def retry_with_backoff(retries=5, base_delay=0.5, factor=2, jitter=0.1):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exc = None
            for attempt in range(retries):
                try:
                    return func(*args, **kwargs)
                except RequestException as e:
                    # Only retry on HTTPError with status >= 500, or other RequestException (like connection errors)
                    if isinstance(e, HTTPError) and e.response is not None and e.response.status_code < 500:
                        raise
                    last_exc = e
                    if attempt == retries - 1:
                        break
                    sleep_time = base_delay * (factor ** attempt) + random.uniform(-jitter, jitter)
                    time.sleep(sleep_time)
            raise last_exc
        return wrapper
    return decorator

@retry_with_backoff()
