// Define the discriminated union
type EventType = 'user_login' | 'file_upload' | 'error';

interface UserLoginEvent {
  type: 'user_login';
  payload: { userId: string; timestamp: number };
}

interface FileUploadEvent {
  type: 'file_upload';
  payload: { fileName: string; sizeBytes: number };
}

interface ErrorEvent {
  type: 'error';
  payload: { message: string; code: number };
}

type ParsedEvent = UserLoginEvent | FileUploadEvent | ErrorEvent;

export function parseEvent(json: string): ParsedEvent {
  const raw = JSON.parse(json);
  return raw as ParsedEvent; // Simplified for brevity, but you can add validation
}

export function describeEvent(event: ParsedEvent): string {
  switch (event.type) {
    case 'user_login':
      return `User ${event.payload.userId} logged in at ${new Date(event.payload.timestamp * 1000).toISOString()}`;
    case 'file_upload':
      return `File ${event.payload.fileName} uploaded (${event.payload.sizeBytes} bytes)`;
    case 'error':
      return `Error code ${event.payload.code}: ${event.payload.message}`;
    default:
      // Exhaustiveness check: should never be reached
      const _exhaustiveCheck: never = event;
      throw new Error(`Unknown event type: ${(_exhaustiveCheck as ParsedEvent).type}`);
  }
}

